\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_database() <> 'picla_local_test' OR inet_server_addr() <> '127.0.0.1'::inet THEN RAISE EXCEPTION 'Solo se ejecuta en la copia local picla_local_test'; END IF; END $$;
DO $$
DECLARE actor uuid; branch uuid; part uuid; part2 uuid; kit uuid; sale uuid; line uuid; old_items jsonb; new_items jsonb; edit uuid:=gen_random_uuid(); stock numeric; result jsonb; caught boolean; qty numeric; amount numeric;
BEGIN
  SELECT u.id INTO actor FROM public.users u JOIN public.roles r ON r.id=u.role_id WHERE r.name='admin' AND u.is_active LIMIT 1;
  IF actor IS NULL THEN RAISE EXCEPTION 'Falta usuario admin para la prueba'; END IF;
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  INSERT INTO public.branches(name) VALUES('LOCAL TEST ONLY') RETURNING id INTO branch;
  PERFORM public.open_cash_session(1000,'Local test',branch);
  INSERT INTO public.parts(branch_id,code,name,price,cost,kit_price,is_active) VALUES(branch,'LOCAL-1','Local product',100,20,80,true) RETURNING id INTO part;
  INSERT INTO public.parts(branch_id,code,name,price,cost,kit_price,is_active) VALUES(branch,'LOCAL-2','Local product 2',100,20,70,true) RETURNING id INTO part2;
  INSERT INTO public.inventory(part_id,branch_id,quantity) VALUES(part,branch,100),(part2,branch,100);
  INSERT INTO public.product_kits(branch_id,code,name) VALUES(branch,'LOCAL-KIT','Kit') RETURNING id INTO kit;
  PERFORM public.update_product_kit(kit,'Kit editado','','General',jsonb_build_array(jsonb_build_object('part_id',part,'quantity',2,'kit_price',80)));
  ASSERT (SELECT count(*)=1 FROM public.product_kit_items WHERE kit_id=kit),'Kit editado';
  SELECT sale_id INTO sale FROM public.pos_create_sale(branch,'LOCAL TEST','cash','BOB',1,'immediate',0,jsonb_build_array(jsonb_build_object('part_id',part,'quantity',2,'unit_price',80,'source_type','kit_component','source_kit_id',kit)),jsonb_build_object('ui_module','pos/sales'));
  SELECT id INTO line FROM public.pos_sale_items WHERE sale_id=sale;
  ASSERT (SELECT quantity=98 FROM public.inventory WHERE part_id=part),'Stock venta kit';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  new_items:=jsonb_build_array(jsonb_build_object('id',line,'part_id',part,'quantity',3,'unit_price',80));
  caught:=false;
  BEGIN PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'No confirmado','[{"method":"cash","amount":80}]',false); EXCEPTION WHEN OTHERS THEN caught:=true; END;
  ASSERT caught,'Rechazar cobro no confirmado';
  ASSERT (SELECT quantity=98 FROM public.inventory WHERE part_id=part),'Rollback stock';
  result:=public.pos_edit_sale(sale,edit,old_items,new_items,'Aumentar kit','[{"method":"cash","amount":30},{"method":"qr","amount":50}]',true);
  ASSERT (result->>'difference')::numeric=80,'Diferencia positiva';
  ASSERT (SELECT quantity=97 FROM public.inventory WHERE part_id=part),'Stock edición';
  PERFORM public.pos_edit_sale(sale,edit,old_items,new_items,'Reintento','[{"method":"cash","amount":30},{"method":"qr","amount":50}]',true);
  ASSERT (SELECT count(*)=2 FROM public.cash_movements WHERE reference_id=edit),'Idempotencia';
  caught:=false;
  BEGIN PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Obsoleto','[]',true); EXCEPTION WHEN OTHERS THEN caught:=true; END;
  ASSERT caught,'Rechazar edición obsoleta';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  new_items:=jsonb_build_array(jsonb_build_object('id',line,'part_id',part,'quantity',1,'unit_price',80));
  result:=public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Reducir kit','[{"method":"cash","amount":160}]',true);
  ASSERT (result->>'difference')::numeric=-160,'Diferencia negativa';
  ASSERT (SELECT quantity=99 FROM public.inventory WHERE part_id=part),'Reposición stock';
  SELECT sum(CASE WHEN movement_type LIKE 'sale_return_%' THEN -m.amount ELSE m.amount END) INTO amount FROM public.cash_movements m WHERE branch_id=branch AND movement_type LIKE 'sale_%';
  ASSERT amount=80,'Caja neta';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  new_items:=jsonb_build_array(jsonb_build_object('id',line,'part_id',part2,'quantity',1,'unit_price',80));
  PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Reemplazo sin diferencia','[]',true);
  ASSERT (SELECT quantity=100 FROM public.inventory WHERE part_id=part),'Reemplazo repone anterior';
  ASSERT (SELECT quantity=99 FROM public.inventory WHERE part_id=part2),'Reemplazo descuenta nuevo';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  caught:=false;
  BEGIN PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,jsonb_build_array(jsonb_build_object('id',line,'part_id',part2,'quantity',1000,'unit_price',80)),'Sin stock','[{"method":"cash","amount":79920}]',true); EXCEPTION WHEN OTHERS THEN caught:=true; END;
  ASSERT caught,'Rechazar stock insuficiente';
  ASSERT (SELECT quantity=99 FROM public.inventory WHERE part_id=part2),'Rollback por stock insuficiente';
  new_items:=old_items || jsonb_build_array(jsonb_build_object('part_id',part,'quantity',1,'unit_price',100));
  PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Agregar producto','[{"method":"qr","amount":100}]',true);
  ASSERT (SELECT count(*)=2 FROM public.pos_sale_items WHERE sale_id=sale),'Agregar línea';
  ASSERT (SELECT sum(sh.amount)=180 FROM public.pos_report_payment_shares((SELECT s FROM public.pos_sales s WHERE id=sale)) sh),'Reporte actualizado';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  new_items:=jsonb_build_array(jsonb_build_object('id',line,'part_id',part2,'quantity',1,'unit_price',80));
  PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Eliminar producto','[{"method":"qr","amount":100}]',true);
  ASSERT (SELECT quantity=100 FROM public.inventory WHERE part_id=part),'Eliminar repone stock';
  SELECT jsonb_agg(jsonb_build_object('id',id,'part_id',part_id,'quantity',quantity,'unit_price',unit_price) ORDER BY id) INTO old_items FROM public.pos_sale_items WHERE sale_id=sale;
  new_items:=jsonb_build_array(jsonb_build_object('id',line,'part_id',part2,'quantity',1,'unit_price',85));
  PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Cambiar precio kit','[{"method":"cash","amount":5}]',true);
  ASSERT (SELECT total_amount=85 FROM public.pos_sales WHERE id=sale),'Precio actualizado';
  PERFORM set_config('request.jwt.claim.sub','',true);
  caught:=false;
  BEGIN PERFORM public.pos_edit_sale(sale,gen_random_uuid(),old_items,new_items,'Sin sesión','[]',true); EXCEPTION WHEN OTHERS THEN caught:=true; END;
  ASSERT caught,'Rechazar usuario sin sesión';
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  caught:=false;
  BEGIN PERFORM public.pos_create_sale(branch,'LOCAL TEST','card','BOB',1,'immediate',0,jsonb_build_array(jsonb_build_object('part_id',part,'quantity',1,'unit_price',100))); EXCEPTION WHEN OTHERS THEN caught:=position('tarjeta' in SQLERRM)>0; END;
  ASSERT caught,'Tarjeta bloqueada';
  caught:=false;
  BEGIN PERFORM public.pos_create_mixed_sale(branch,'LOCAL TEST','cash','BOB',1,'immediate',0,jsonb_build_array(jsonb_build_object('part_id',part,'quantity',1,'unit_price',100)),'{}','[{"method":"cash","amount":50},{"method":"card","amount":50}]'); EXCEPTION WHEN OTHERS THEN caught:=position('tarjeta' in SQLERRM)>0; END;
  ASSERT caught,'Tarjeta mixta bloqueada';
  PERFORM public.pos_void_sale(sale,'Prueba posterior a edición');
  ASSERT (SELECT quantity=100 FROM public.inventory WHERE part_id=part2),'Anulación repone stock editado';
  SELECT sum(CASE WHEN movement_type LIKE 'sale_return_%' THEN -m.amount ELSE m.amount END) INTO amount FROM public.cash_movements m WHERE branch_id=branch AND movement_type LIKE 'sale_%';
  ASSERT amount=0,'Anulación revierte recaudación neta';
  ASSERT NOT EXISTS(SELECT 1 FROM public.cash_movements m WHERE branch_id=branch AND movement_type LIKE 'sale_%' GROUP BY payment_method HAVING sum(CASE WHEN movement_type LIKE 'sale_return_%' THEN -m.amount ELSE m.amount END)<>0),'Anulación revierte también cada método';
  RAISE NOTICE 'PASS: kit, venta, aumento, devolución, reemplazo, confirmación, idempotencia, concurrencia, tarjeta simple/mixta, caja, stock y anulación';
END $$;
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK;
